var n=`0456-pide`;var a=`world-0456`;var t=`TR`;var o=`western-asia`;var r=8;var l=99;var s={en:`Pide`,ua:`Піде`};var u={en:`A traditional dish from Türkiye, centered on all-purpose flour, instant yeast, feta, mozzarella. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: пшеничне борошно універсальне, інстантні дріжджі, фета, моцарела. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`all-purpose-flour`,480,`g`],[`water`,260,`ml`],[`instant-yeast`,6,`g`],[`white-granulated-sugar`,7,`g`],[`extra-virgin-olive-oil`,30,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:8,i:[[`feta`,220,`g`],[`mozzarella`,160,`g`],[`parsley`,20,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 10 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 10 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:10,i:[]},{en:`Bake in a thoroughly preheated 230–250°C oven for about 16 minutes until the crust is deeply golden and the filling is cooked.`,ua:`Випікайте в добре розігрітій до 230–250°C духовці приблизно 16 хвилин до насичено-золотистої скоринки та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:16,i:[[`chicken-egg`,1,`pcs`]]}];var d={slug:n,id:a,country:`TR`,region:o,servings:8,minutes:99,title:s,text:u,steps:g};export{t as country,d as default,a as id,l as minutes,o as region,r as servings,n as slug,g as steps,u as text,s as title};